// 叠纸游戏背景图。四款均为官方壁纸/主视觉（内联 webp，1600×900）。

export const DEEPSPACE_BG = "data:image/webp;base64,"

export const INFINITY_NIKKI_BG = "data:image/webp;base64,"

export const LOVE_PRODUCER_BG = "data:image/webp;base64,"

export const SHINING_NIKKI_BG = "data:image/webp;base64,"

/** 背景项：key 用于持久化，name 是中文显示名，css 是 CSS background-image 值。 */
export interface GameBackground {
  key: string
  name: string
  /** CSS `background-image` 值：`url(...)` 或 `linear-gradient(...)` 占位。 */
  css: string
}

/** 四款叠纸游戏背景。 */
export const GAME_BACKGROUNDS: GameBackground[] = [
  { key: 'love-deepspace', name: '恋与深空', css: `url("${DEEPSPACE_BG}")` },
  { key: 'shining-nikki', name: '闪耀暖暖', css: `url("${SHINING_NIKKI_BG}")` },
  { key: 'infinity-nikki', name: '无限暖暖', css: `url("${INFINITY_NIKKI_BG}")` },
  { key: 'love-producer', name: '恋与制作人', css: `url("${LOVE_PRODUCER_BG}")` },
]

/** 默认背景（首次使用）。 */
export const DEFAULT_BG_KEY = 'love-deepspace'

/** localStorage 键：记住用户选择。 */
const BG_STORAGE_KEY = 'pet-panel:background'

/** 读取已保存的背景 key，未保存则回默认。 */
export function getStoredBackground(): string {
  try {
    const key = localStorage.getItem(BG_STORAGE_KEY)
    if (key && GAME_BACKGROUNDS.some((b) => b.key === key)) return key
  } catch {
    /* localStorage 不可用时回默认 */
  }
  return DEFAULT_BG_KEY
}

/** 应用背景：写入 body 的 --pg-bg-image CSS 变量并持久化选择。 */
export function applyBackground(key: string): void {
  const bg = GAME_BACKGROUNDS.find((b) => b.key === key)
  if (!bg) return
  document.body.style.setProperty('--pg-bg-image', bg.css)
  try {
    localStorage.setItem(BG_STORAGE_KEY, key)
  } catch {
    /* 忽略持久化失败 */
  }
}

/** 背景明暗：0 = 最明显（玻璃透明 + 原图亮度），1 = 最暗（玻璃厚 + 遮罩深）。 */
export const DEFAULT_BG_DIM = 0.3
export const BG_DIM_MIN = 0
export const BG_DIM_MAX = 1

/** localStorage 键：记住明暗选择。 */
const DIM_STORAGE_KEY = 'pet-panel:background-dim'

/** 读取已保存的明暗值，未保存则回默认。 */
export function getStoredDim(): number {
  try {
    const raw = localStorage.getItem(DIM_STORAGE_KEY)
    if (raw !== null) {
      const v = Number.parseFloat(raw)
      if (Number.isFinite(v)) return clampDim(v)
    }
  } catch {
    /* localStorage 不可用时回默认 */
  }
  return DEFAULT_BG_DIM
}

/** 夹取到 [MIN, MAX]。 */
function clampDim(v: number): number {
  return Math.min(BG_DIM_MAX, Math.max(BG_DIM_MIN, v))
}

/** 应用明暗：同时联动黑色遮罩 + 玻璃层透明度，并持久化。 */
export function applyDim(t: number): void {
  const v = clampDim(t)
  // 黑色遮罩：0（原图亮度）→ 0.7（压暗）。
  const dim = v * 0.7
  document.body.style.setProperty('--pg-bg-dim', String(dim))
  // 玻璃层透明度：0.2（背景透出最多）→ 0.74（背景被盖住，文字最清晰）。
  const glass = (0.2 + v * 0.54).toFixed(3)
  const glassRgba = `rgba(255,255,255,${glass})`
  document.body.style.setProperty('--dsw-specific-sidebar-fill', glassRgba)
  document.body.style.setProperty('--dsw-alias-bg-base', glassRgba)
  document.body.style.setProperty('--dsw-alias-bg-layer-1', glassRgba)
  document.body.style.setProperty('--dsw-alias-bg-layer-2', glassRgba)
  document.body.style.setProperty('--dsw-alias-bg-layer-3', glassRgba)
  try {
    localStorage.setItem(DIM_STORAGE_KEY, String(v))
  } catch {
    /* 忽略持久化失败 */
  }
}
